try {
    var result = [];
    csh();

    var push = (title, url, size) => result.push({
        "title": title,
        "url": url,
        "style": {
            "layout_flexGrow": 1,
            "layout_flexBasisPercent": size
        }
    });

    // 主切换筛选器: 人气热门/更新时间/新品上架/排行榜
    result.push(createFilter(
        "分类",
        ["人气热门", "更新时间", "新品上架", "排行榜"],
        "人气热门",
        "mainType",
        1
    ));

    var mainType = Get("mainType");
    infoMap.save();

    // 排序方式映射到URL片段
    var order_dic = {
        "人气热门": "",
        "更新时间": "order2",
        "新品上架": "order18"
    };

    // 题材映射
    var tag_dic = {
        "全部": "",
        "热血": "tag1",
        "恋爱": "tag2",
        "百合": "tag4",
        "彩虹": "tag5",
